/**
 * Upload validation. Pure (no I/O) so it is unit-tested exhaustively. A file is accepted only when ALL of these agree:
 * the extension is on the allow-list, the declared MIME type is one that extension may have, and the first bytes match
 * the real format ("magic bytes"). Names are never trusted: the stored key is generated by the server, and the original
 * name is only kept as sanitized display text.
 */
export const MAX_FILE_BYTES = 10 * 1024 * 1024;
export const MAX_FILES_PER_SUBMISSION = 5;

interface FileKind {
  mime: string;
  /** MIME types browsers may declare for this extension. */
  declared: readonly string[];
  magic?: readonly number[];
  text?: boolean;
}

const KINDS: Record<string, FileKind> = {
  pdf: { mime: "application/pdf", declared: ["application/pdf"], magic: [0x25, 0x50, 0x44, 0x46, 0x2d] },
  png: { mime: "image/png", declared: ["image/png"], magic: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] },
  jpg: { mime: "image/jpeg", declared: ["image/jpeg"], magic: [0xff, 0xd8, 0xff] },
  jpeg: { mime: "image/jpeg", declared: ["image/jpeg"], magic: [0xff, 0xd8, 0xff] },
  zip: { mime: "application/zip", declared: ["application/zip", "application/x-zip-compressed"], magic: [0x50, 0x4b, 0x03, 0x04] },
  txt: { mime: "text/plain", declared: ["text/plain"], text: true },
  md: { mime: "text/markdown", declared: ["text/markdown", "text/x-markdown", "text/plain"], text: true },
};

export const ALLOWED_EXTENSIONS = Object.keys(KINDS);

export type UploadCheck = { ok: true; extension: string; mime: string; displayName: string } | { ok: false; reason: string };

/** Display name: no path parts, no control or markup characters, bounded length. Never used to build a path. */
export function sanitizeFileName(name: string): string {
  const base = name.split(/[\\/]/).pop() ?? "";
  const clean = base.replace(/[\u0000-\u001f\u007f<>:"|?*]/g, "").replace(/\s+/g, " ").trim().replace(/^\.+/, "");
  return (clean || "file").slice(0, 100);
}

function startsWith(bytes: Uint8Array, magic: readonly number[]): boolean {
  return bytes.length >= magic.length && magic.every((b, i) => bytes[i] === b);
}

/**
 * Everything that can be decided without the file's bytes: size, extension and declared MIME type. Used before a direct
 * upload is authorized; the bytes themselves are checked afterwards by `validateUpload` (which calls this first).
 */
export function validateUploadMeta(input: { name: string; declaredMime: string; size: number }): UploadCheck {
  if (!Number.isInteger(input.size) || input.size <= 0) return { ok: false, reason: "The file is empty." };
  if (input.size > MAX_FILE_BYTES) return { ok: false, reason: `The file is larger than ${MAX_FILE_BYTES / 1024 / 1024} MB.` };
  const displayName = sanitizeFileName(input.name);
  const dot = displayName.lastIndexOf(".");
  const extension = dot > 0 ? displayName.slice(dot + 1).toLowerCase() : "";
  const kind = KINDS[extension];
  if (!kind) return { ok: false, reason: `Files of this type are not allowed. Allowed: ${ALLOWED_EXTENSIONS.join(", ")}.` };
  const declared = input.declaredMime.split(";")[0].trim().toLowerCase();
  if (declared && declared !== "application/octet-stream" && !kind.declared.includes(declared)) {
    return { ok: false, reason: "The file type does not match its extension." };
  }
  return { ok: true, extension, mime: kind.mime, displayName };
}

export function validateUpload(input: { name: string; declaredMime: string; bytes: Uint8Array }): UploadCheck {
  const { bytes } = input;
  const meta = validateUploadMeta({ name: input.name, declaredMime: input.declaredMime, size: bytes.length });
  if (!meta.ok) return meta;
  const kind = KINDS[meta.extension];
  if (kind.magic && !startsWith(bytes, kind.magic)) return { ok: false, reason: "The file content does not match its extension." };
  if (kind.text) {
    if (bytes.includes(0)) return { ok: false, reason: "The file content does not match its extension." };
    try {
      new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    } catch {
      return { ok: false, reason: "Text files must be UTF-8." };
    }
  }
  return meta;
}
